        d_model: usize,
        d_ff: usize,
        num_heads: usize,
        nl_oob_config: Option<BiasFunction>,
        nl_oob_max_scale: Option<f32>,
        t_max: usize,
        beta: f32,
    ) -> Result<Self, String> {
