                nl_oob_max_scale.unwrap_or(2.0),
            )?
        } else {
            TransformerBlock::new_with_kv_and_rope(TransformerConfig {
                d_model,
                d_ff,
                num_heads,
                kv_heads: num_heads,
                use_rope: false,
                rope_theta: 10000.0,
                rope_scale: 1.0,
